import itertools
from dataclasses import dataclass
from fractions import Fraction


@dataclass(frozen=True)
class Blob:
    oid: str
    tenant: str
    size: int
    borrowed: bool
    cache_only: bool
    refs: int


def reference_admit(blobs, capacity, tenant_cap, tenant_used, demand):
    if demand < 0 or capacity < 0 or tenant_cap < 0 or tenant_used < 0:
        return False, ()
    used = sum(b.size for b in blobs)
    if used > capacity:
        return False, ()
    if tenant_used + demand > tenant_cap:
        return False, ()
    free = capacity - used
    candidates = sorted(
        [b for b in blobs if b.cache_only and b.refs == 0],
        key=lambda b: b.oid,
    )
    for count in range(len(candidates) + 1):
        for combo in itertools.combinations(candidates, count):
            freed = sum(b.size for b in combo)
            if free + freed >= demand:
                return True, tuple(b.oid for b in combo)
    return False, ()


def unsafe_admit(blobs, capacity, tenant_cap, tenant_used, demand):
    used = sum(b.size for b in blobs)
    reclaimed = sum(b.size for b in blobs if b.borrowed)
    return tenant_used + demand <= tenant_cap and used - reclaimed + demand <= capacity


def no_reclaim_admit(blobs, capacity, tenant_cap, tenant_used, demand):
    used = sum(b.size for b in blobs)
    return tenant_used + demand <= tenant_cap and capacity - used >= demand


@dataclass(frozen=True)
class CacheEntry:
    key: str
    scope: frozenset
    namespace: str
    model: str
    adapter: str
    ready: bool
    generation: int
    payload: str


def reference_lookup(entries, principal, key, namespace, model, adapter, generation):
    matches = [
        e.payload
        for e in entries
        if e.key == key
        and principal in e.scope
        and e.namespace == namespace
        and e.model == model
        and e.adapter == adapter
        and e.ready
        and e.generation == generation
    ]
    return tuple(sorted(matches))


def key_only_lookup(entries, key):
    matches = [e for e in entries if e.key == key]
    if not matches:
        return ()
    return (matches[-1].payload,)


@dataclass(frozen=True)
class Replica:
    rid: str
    capacity: int
    domains: frozenset


def all_domains(replicas):
    out = set()
    for r in replicas:
    	out.update(r.domains)
    return out


def reference_min_surviving(replicas):
    domains = sorted(all_domains(replicas))
    if not domains:
        return sum(r.capacity for r in replicas)
    return min(
        sum(r.capacity for r in replicas if d not in r.domains)
        for d in domains
    )


def unsafe_min_surviving(replicas):
    return sum(r.capacity for r in replicas)


def reference_cpu_target(weights, active, capacity):
    active = tuple(sorted(active))
    if not active:
        return {}
    total = sum(weights[t] for t in active)
    return {t: Fraction(capacity * weights[t], total) for t in active}


def equal_cpu_target(active, capacity):
    active = tuple(sorted(active))
    if not active:
        return {}
    return {t: Fraction(capacity, len(active)) for t in active}


def main():
    blobs = (
        Blob('a1', 'A', 3, False, False, 1),
        Blob('a2', 'A', 2, True, False, 1),
        Blob('a3', 'A', 1, True, True, 0),
    )
    ok3, ev3 = reference_admit(blobs, 8, 8, 0, 3)
    assert ok3 and ev3 == ('a3',)
    remaining = sum(b.size for b in blobs if b.oid not in ev3)
    assert remaining + 3 <= 8 and remaining == 5

    ok4, ev4 = reference_admit(blobs, 8, 8, 0, 4)
    unsafe4 = unsafe_admit(blobs, 8, 8, 0, 4)
    assert not ok4 and ev4 == ()
    assert unsafe4

    no3 = no_reclaim_admit(blobs, 8, 8, 0, 3)
    assert not no3
    assert reference_admit(blobs, 8, 8, 0, 0)[0]
    assert not reference_admit(blobs, 8, 0, 0, 1)[0]
    print('[capacity] demand3 legal with eviction', ev3, 'remaining-plus-demand', remaining + 3)
    print('[capacity] demand4 rejected by enumeration; unsafe borrowed-page control accepted', unsafe4)
    print('[capacity] free-only control rejected legal demand3, detected', not no3)

    entries = (
        CacheEntry('h', frozenset(('A',)), 'nsA', 'm1', 'a1', True, 1, 'A-only'),
        CacheEntry('h', frozenset(('B',)), 'nsB', 'm1', 'a1', True, 2, 'B-only'),
        CacheEntry('h', frozenset(('A',)), 'nsA', 'm1', 'a2', True, 2, 'A-other-adapter'),
        CacheEntry('h', frozenset(('A',)), 'nsA', 'm1', 'a1', False, 2, 'not-ready'),
        CacheEntry('h', frozenset(('A',)), 'nsA', 'm1', 'a1', True, 0, 'old-generation'),
    )
    safe = reference_lookup(entries, 'A', 'h', 'nsA', 'm1', 'a1', 1)
    buggy = key_only_lookup(entries, 'h')
    wrong_ns = reference_lookup(entries, 'A', 'h', 'nsB', 'm1', 'a1', 1)
    wrong_adapter = reference_lookup(entries, 'A', 'h', 'nsA', 'm1', 'a2', 1)
    stale = reference_lookup(entries, 'A', 'h', 'nsA', 'm1', 'a1', 2)
    assert safe == ('A-only',)
    assert buggy != safe
    assert wrong_ns == ()
    assert wrong_adapter == ()
    assert stale == ()
    print('[cache] authorized full identity hit', safe)
    print('[cache] key-only negative control returned', buggy, 'detected', buggy != safe)
    print('[cache] namespace/adapter/stale generation filters', wrong_ns, wrong_adapter, stale)

    good = (
        Replica('r1', 30, frozenset(('h1', 'rack1'))),
        Replica('r2', 35, frozenset(('h2', 'rack2'))),
    )
    shared = (
        Replica('x', 40, frozenset(('host1', 'rackA'))),
        Replica('y', 40, frozenset(('host1', 'rackA'))),
    )
    assert reference_min_surviving(good) == 30
    assert unsafe_min_surviving(good) == 65
    assert reference_min_surviving(good) >= 30
    assert not (reference_min_surviving(good) >= 40)
    assert unsafe_min_surviving(good) >= 40
    assert reference_min_surviving(shared) == 0
    assert unsafe_min_surviving(shared) == 80
    assert not (reference_min_surviving(shared) >= 35)
    assert unsafe_min_surviving(shared) >= 35
    print('[fault] spread replicas min after one failure', reference_min_surviving(good))
    print('[fault] shared-domain replicas min after one failure', reference_min_surviving(shared))
    print('[fault] domain-ignoring negative control sum', unsafe_min_surviving(shared), 'detected', reference_min_surviving(shared) != unsafe_min_surviving(shared))

    weights = {'A': 1, 'B': 3}
    target = reference_cpu_target(weights, ('A', 'B'), 4)
    equal = equal_cpu_target(('A', 'B'), 4)
    assert target == {'A': Fraction(1, 1), 'B': Fraction(3, 1)}
    assert equal == {'A': Fraction(2, 1), 'B': Fraction(2, 1)}
    assert target != equal
    assert reference_cpu_target(weights, (), 4) == {}
    print('[fair-share] weighted target', target)
    print('[fair-share] equal-share negative control', equal, 'detected', target != equal)

    print('scoped observations complete: capacity, cache, fault, and CPU-share models agree with independent references where expected')


if __name__ == '__main__':
    main()
